    a = False

for x in range(len(each_place)-1):
  if each_place[x][0] == each_place[x+1][0]:
    a = False
    break
if a:
    ans = 0
    for y in range(len(each_place)):
        ans += 10 ** (n-each_place[y][0]) * each_place[y][1]
    print(ans)
else:
    print(-1)

